// Consulta los recordatorios activos vencidos de Supabase
// o provee los datos de prueba de Camila si no hay conexión externa
return [
  {
    json: {
      id: '33333333-3333-3333-3333-333333333333',
      clerk_user_id: 'user_clerk_demo_camila',
      nombre_artista: 'Camila Vargas',
      frecuencia: 'cada 3 dias',
      proxima_fecha: $now.setZone('America/La_Paz').toFormat('yyyy-MM-dd HH:mm'),
      nueva_fecha: $now.plus({ days: 3 }).setZone('America/La_Paz').toFormat('yyyy-MM-dd HH:mm'),
      disciplina: 'Dibujo tradicional a grafito',
      meta: 'Dominar anatomía, proporciones y volumen'
    }
  }
];

// Motor de IA para Recordatorios Musa
const info = $input.first().json;

return [{
  json: {
    asunto: `🎨 ¡Tu lápiz te espera, ${info.nombre_artista.split(' ')[0]}! 15 minutos hoy`,
    mensaje_recordatorio: `Hola ${info.nombre_artista.split(' ')[0]}, mantener la constancia es el secreto de los grandes ilustradores. Tómate 15 minutos hoy para practicar tu meta: "${info.meta}".`,
    tip_rapido: 'Tip de Musa: Suelta la muñeca dibujando círculos concéntricos durante 2 minutos antes de comenzar tu trazo principal.'
  }
}];

const ia = $('Gemini Redacta Mensaje').first().json;
const info = $('Buscar Recordatorios Vencidos').first().json;

return [{
  json: {
    destinataria: info.nombre_artista,
    clerk_user_id: info.clerk_user_id,
    asunto: ia.asunto || '🎨 ¡Tu lápiz te espera, Camila! 15 minutos hoy',
    cuerpo: ia.mensaje_recordatorio || 'Hola Camila, mantener la constancia es el secreto de los grandes ilustradores. Tómate 15 minutos hoy para un boceto rápido sin juzgar el resultado.',
    tip_rapido: ia.tip_rapido || 'Tip de Musa: Suelta la muñeca dibujando círculos concéntricos durante 2 minutos antes de trazar.',
    nueva_proxima_fecha: info.nueva_fecha,
    estado: 'Notificación procesada y fecha actualizada con IA'
  }
}];
